import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Navbar from "./components/Navbar";

// الصفحات
import Home from "./pages/Home";
import SamplesInput from "./Pages/SamplesInput";
import FeaturesInput from "./Pages/FeaturesInput";


function App() {
  return (
    <Router>
      {/* ✅ شريط التنقل الثابت في الأعلى */}
      <Navbar />

      {/* ✅ المحتوى المتغير حسب الصفحة */}
      <div className="page-content">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/samples" element={<SamplesInput/>} />
          <Route path="/features" element={<FeaturesInput />} />
          <Route path="/results" element={<R />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
